// inside consume(...) with .autoAck(false)
try {
  const res = await queen.transaction()
    .ack(message, 'completed', { consumerGroup: 'mailer' })
    .queue('emails').push([{ transactionId: `welcome-${userId}`, data: mail }])
    .once('welcome', String(userId), { ttl: '7d' })
    .commit()
  if (res.success === false) await queen.ack(message, 'completed', { group: 'mailer' }) // kv_precondition
} catch (err) {
  if (err.reason === 'duplicate') await queen.ack(message, 'completed', { group: 'mailer' })
  else if (err.reason !== 'rejected_ack') await queen.ack(message, 'failed', { group: 'mailer', error: err.message })
}

